import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

function Register() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: '', email: '', phone: '', password: '', agree: false });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({ ...prev, [name]: type === 'checkbox' ? checked : value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    navigate('/choose-role');
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: '#F8F9FA', padding: '20px' }}>
      <div style={{ width: '100%', maxWidth: '402px', background: 'white', padding: '32px 24px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700 }}>Gabung WORKIE</h1>
        <p style={{ color: '#475569', marginBottom: '24px' }}>Mulai dapatkan pekerjaan instan atau rekrut pekerja terlatih hari ini.</p>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Nama Lengkap</label>
            <input name="name" placeholder="Contoh: Andi Wijaya" value={form.name} onChange={handleChange} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Email</label>
            <input name="email" type="email" placeholder="Contoh: andi@gmail.com" value={form.email} onChange={handleChange} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Nomor HP</label>
            <input name="phone" placeholder="Contoh: 08123456789" value={form.phone} onChange={handleChange} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Kata Sandi</label>
            <input name="password" type="password" placeholder="Minimal 8 karakter" value={form.password} onChange={handleChange} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px', marginBottom: '16px' }}>
            <input name="agree" type="checkbox" checked={form.agree} onChange={handleChange} style={{ marginTop: '3px', width: '18px', height: '18px', accentColor: '#0D9488' }} />
            <label style={{ fontSize: '14px', color: '#475569' }}>Saya menyetujui Syarat & Ketentuan serta Kebijakan Privasi WORKIE.</label>
          </div>
          <button type="submit" style={{ width: '100%', padding: '14px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontSize: '16px', fontWeight: 700 }}>Daftar</button>
        </form>
        <div style={{ textAlign: 'center', marginTop: '16px', fontSize: '14px' }}>Sudah punya akun? <Link to="/" style={{ color: '#0D9488', fontWeight: 600 }}>Masuk</Link></div>
      </div>
    </div>
  );
}

export default Register;
